-- 60 Moonlit Duel: the duellists are on light layer 2, the world on
-- layer 1, and every light says which it lights (`light_mask`). This plays
-- the duel - step in, clash, step back - flashes the lightning, and with L
-- turns the layers off (every light on everything) and on again.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/60-moonlit-duel.scene"
local ALL = 4294967295
local MASKS = { MoonLight = 1, KeyLeft = 2, KeyRight = 2, Lightning = 1, ClashLight = 2 }
local captions = true
local layered = true
local status
local lights = {}
local left, right = {}, {}
local sparks, clash, bolt
local t, next_bolt, flash = 0, 3.0, 0
local swing = 0

function init(entity)
    status = Entity.find_by_name("Status")
    for name, _ in pairs(MASKS) do lights[name] = Entity.find_by_name(name) end
    left = { low = Entity.find_by_name("LeftLow"), high = Entity.find_by_name("LeftHigh") }
    right = { low = Entity.find_by_name("RightLow"), high = Entity.find_by_name("RightHigh") }
    sparks = Entity.find_by_name("Sparks")
    clash = lights.ClashLight
    bolt = lights.Lightning
end

local function set_layers(on)
    for name, e in pairs(lights) do
        if e then Lighting.set_mask(e, on and MASKS[name] or ALL) end
    end
end

local function place(f, x, high)
    for _, e in pairs({ f.low, f.high }) do
        if e then Transform.set_position(e, x, -166) end
    end
    if f.low then Sprite.set_color(f.low, 1, 1, 1, high and 0 or 1) end
    if f.high then Sprite.set_color(f.high, 1, 1, 1, high and 1 or 0) end
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("L") then layered = not layered; set_layers(layered) end
    t = t + dt
    -- The duel: a 3.2 s cycle - circle, close in, clash at 1.6 s, part.
    local phase = (t % 3.2) / 3.2
    local close = math.max(0, math.sin(phase * math.pi)) ^ 3
    local gap = 175 - 120 * close + 6 * math.sin(t * 1.7)
    local high = phase > 0.42 and phase < 0.62
    place(left, -gap, high)
    place(right, gap, high)
    if high and swing == 0 then
        swing = 1
        if sparks then Particles.emit_burst(sparks, 40) end
    elseif not high then
        swing = 0
    end
    if clash then Lighting.set_intensity(clash, high and (3.0 + math.random() * 1.5) or 0) end
    -- Lightning: now and then, a double flash over the background.
    if t > next_bolt then
        flash = 0.5
        next_bolt = t + 4 + math.random() * 5
    end
    flash = math.max(0, flash - dt)
    local f = 0
    if flash > 0.38 then f = 3.5 elseif flash > 0.3 then f = 0.4 elseif flash > 0.18 then f = 2.6 * (flash - 0.18) / 0.12 end
    if bolt then Lighting.set_intensity(bolt, f) end
    if status then
        UI.set_text(status, layered and "light layers on: each light lights its own" or "light layers off: every light on everything")
    end
end
